/** Test-only reader/executor of the actual SSR macro tree. QS74 was transcribed
 * independently here; neither the production MacroLines nor its model is imported.
 * HTML is parsed as inert text, and only the exam's fixed statements are accepted. */
import {independentPm13Parse,independentPm13Evaluate,independentPm13Assign,type Pm13Cell,type Pm13Sheets} from './legacy-2017-autumn-pm13-expression-oracle';
type Element={tag:string;attrs:Record<string,string>;children:(Element|string)[]};
type Line={kind:'line';index:number;text:string};
type Hole={kind:'hole';name:string};
type Loop={kind:'while';role:'outer'|'inner';condition:Line|Hole;body:Statement[]};
type Branch={kind:'if';condition:Hole;yes:Statement[];no:Statement[]};
type Statement=Line|Hole|Loop|Branch;
export type RenderedPm13Macro={declarations:Line[];statements:Statement[]};
const normalize=(s:string)=>s.replaceAll(/\s/g,''),decode=(s:string)=>s.replaceAll('&quot;','"').replaceAll('&#x27;',"'").replaceAll('&amp;','&').replaceAll('&lt;','<').replaceAll('&gt;','>');
function fail():never{throw Error('ORACLE_MACRO_RENDER_STRUCTURE');}
const elements=(e:Element)=>e.children.filter((c):c is Element=>typeof c!=='string');
const text=(e:Element):string=>e.children.map(c=>typeof c==='string'?c:text(c)).join('');
function htmlTree(html:string){const root:Element={tag:'root',attrs:{},children:[]},stack=[root];for(const match of html.matchAll(/<[^>]*>|[^<]+/g)){const token=match[0];if(token.startsWith('</')){const tag=token.slice(2,-1);if(stack.length<2||stack.pop()!.tag!==tag)fail();}else if(token.startsWith('<')){const tag=token.match(/^<([a-z0-9-]+)/)?.[1];if(!tag)fail();const attrs:Record<string,string>={};for(const m of token.matchAll(/([a-zA-Z0-9_-]+)="([^"]*)"/g)){if(Object.hasOwn(attrs,m[1]))fail();attrs[m[1]]=decode(m[2]);}const node:Element={tag,attrs,children:[]};stack.at(-1)!.children.push(node);if(!token.endsWith('/>')&&!['br','img','hr','input'].includes(tag))stack.push(node);}else stack.at(-1)!.children.push(decode(token));}if(stack.length!==1)fail();return root;}
function collect(e:Element,attribute:string):Element[]{return[...(Object.hasOwn(e.attrs,attribute)?[e]:[]),...elements(e).flatMap(child=>collect(child,attribute))];}
function assertChildren(e:Element,count:number){const list=elements(e);if(list.length!==count||e.children.some(c=>typeof c==='string'&&c.trim()))fail();return list;}
function readLine(e:Element):Line{if(!Object.hasOwn(e.attrs,'data-autumn-pm13-line')||elements(e).length)fail();const index=Number(e.attrs['data-autumn-pm13-line']);if(!Number.isInteger(index))fail();let value=text(e);if(e.attrs.class==='autumn-pm13-operation'){if(!value.startsWith('・'))fail();value=value.slice(1);}return{kind:'line',index,text:normalize(value)};}
function readHole(e:Element):Hole{if(e.tag!=='span'||e.attrs.class!=='autumn-pm13-hole'||elements(e).length||text(e)!==e.attrs['data-autumn-pm13-hole'])fail();return{kind:'hole',name:e.attrs['data-autumn-pm13-hole']};}
function readCondition(e:Element,symbol:string){const [mark,value]=assertChildren(e,2);if(e.attrs.class!=='autumn-pm13-condition'||mark.attrs.class!=='autumn-pm13-control'||text(mark)!==symbol)fail();return Object.hasOwn(value.attrs,'data-autumn-pm13-line')?readLine(value):readHole(value);}
function readStatement(e:Element):Statement{if(Object.hasOwn(e.attrs,'data-autumn-pm13-line'))return readLine(e);if(Object.hasOwn(e.attrs,'data-autumn-pm13-loop')){const [condition,indent,end]=assertChildren(e,3);if(e.attrs.class!=='autumn-pm13-loop'||indent.attrs.class!=='autumn-pm13-indent'||end.attrs.class!=='autumn-pm13-loop-end'||text(end)!=='■')fail();const role=e.attrs['data-autumn-pm13-loop'];if(role!=='outer'&&role!=='inner')fail();return{kind:'while',role,condition:readCondition(condition,'■'),body:elements(indent).map(readStatement)};}if(e.attrs['data-autumn-pm13-if']==='two_branches'){const [condition,yes,otherwise,no,end]=assertChildren(e,5),test=readCondition(condition,'▲');if(test.kind!=='hole'||e.attrs.class!=='autumn-pm13-if'||yes.attrs.class!=='autumn-pm13-indent'||otherwise.attrs.class!=='autumn-pm13-else'||text(otherwise)!==''||no.attrs.class!=='autumn-pm13-indent autumn-pm13-operation'||end.attrs.class!=='autumn-pm13-if-end'||text(end)!=='▼')fail();const children=elements(no);if(children.length!==1||no.children.filter(c=>typeof c==='string').join('')!=='・')fail();return{kind:'if',condition:test,yes:elements(yes).map(readStatement),no:[readHole(children[0])]};}fail();}
const line=(index:number,text:string):Line=>({kind:'line',index,text:normalize(text)}),hole=(name:string):Hole=>({kind:'hole',name});
/** Frozen from QS74: initialisation precedes the outer pre-test loop; progression
 * follows both branches inside that loop. The inner loop precedes the branch. */
export const autumnPm13OriginalRenderedMacro:RenderedPm13Macro={declarations:[line(0,'○マクロ: Page_count'),line(1,'○数値型: log_line, count_line'),line(2,'○文字列型: log_url, count_url')],statements:[line(3,'log_line ← 1'),{kind:'while',role:'outer',condition:line(4,'相対(ログ!A1, log_line, 2) ≠ null'),body:[line(5,'count_line ← 1'),line(6,'log_url ← 相対(ログ!A1, log_line, 2)'),line(7,'count_url ← 相対(A1, count_line, 0)'),{kind:'while',role:'inner',condition:hole('d'),body:[line(9,'count_line ← count_line + 1'),line(10,'count_url ← 相対(A1, count_line, 0)')]},{kind:'if',condition:hole('e'),yes:[line(12,'相対(A1, count_line, 0) ← log_url'),line(13,'相対(A1, count_line, 1) ← 1')],no:[hole('f')]},line(15,'log_line ← log_line + 1')]}]};
export function independentPm13ReadRenderedMacro(html:string):RenderedPm13Macro{const roots=collect(htmlTree(html),'data-autumn-pm13-macro');if(roots.length!==1||roots[0].attrs['data-autumn-pm13-macro']!=='Page_count')fail();const children=assertChildren(roots[0],5),program={declarations:children.slice(0,3).map(readLine),statements:children.slice(3).map(readStatement)};if(JSON.stringify(program)!==JSON.stringify(autumnPm13OriginalRenderedMacro))fail();return program;}
/** Executes the *read* statements and nesting. The reference tally uses separate
 * ordered arrays; this executor only interprets the closed spreadsheet AST. */
export function independentPm13ExecuteRenderedMacro(program:RenderedPm13Macro,input:string[],d:string,e:string,f:string){if(input.length>9998||input.some(s=>!s))throw Error('ORACLE_MACRO_INPUT');const sheets:Pm13Sheets={ログ:new Map(),集計:new Map()},env:Record<string,Pm13Cell>={},holes:Record<string,string>={d,e,f};input.forEach((value,i)=>sheets.ログ.set('C'+(i+2),value));let steps=0;const budget=Math.min(200000000,(input.length+1)**2*20+200),tick=()=>{if(++steps>budget)throw Error('ORACLE_MACRO_NONTERMINATION');};
 for(const declaration of program.declarations.slice(1)){const parts=declaration.text.split(':');if(parts.length!==2)fail();for(const name of parts[1].split(',')){if(!/^(?:log_line|count_line|log_url|count_url)$/.test(name)||Object.hasOwn(env,name))fail();env[name]=null;}}
 const expression=(s:Line|Hole)=>s.kind==='hole'?holes[s.name]:s.text,parseCache=new Map<string,ReturnType<typeof independentPm13Parse>>(),evaluate=(value:string)=>{let parsed=parseCache.get(value);if(!parsed){parsed=independentPm13Parse(value);parseCache.set(value,parsed);}return independentPm13Evaluate(parsed,sheets,env);},condition=(s:Line|Hole)=>{const value=evaluate(expression(s));if(typeof value!=='boolean')throw Error('ORACLE_MACRO_BOOLEAN');return value;};
 function execute(statements:Statement[]){for(const statement of statements){tick();if(statement.kind==='while'){while(condition(statement.condition)){tick();execute(statement.body);}continue;}if(statement.kind==='if'){execute(condition(statement.condition)?statement.yes:statement.no);continue;}const value=expression(statement),parts=value.split('←');if(parts.length!==2)throw Error('ORACLE_MACRO_ASSIGN');if(/^[a-z_]+$/.test(parts[0])){if(!Object.hasOwn(env,parts[0]))fail();const result=evaluate(parts[1]);if(result&&typeof result==='object')fail();env[parts[0]]=result;}else independentPm13Assign(value,sheets,env);}}
 execute(program.statements);const output:[Pm13Cell,Pm13Cell][]=[];for(let row=2;row<=Math.min(10000,input.length+2);row++){const url=sheets.集計.get('A'+row)??null,count=sheets.集計.get('B'+row)??null;if(url!==null||count!==null)output.push([url,count]);}return{output,steps,sheets};}
